import { NavLink, useNavigate } from "react-router-dom";
import useAuth from "../hooks/useAuth";
import useCart from "../hooks/useCart";

const publicLinks = [
  { to: "/", label: "Home" },
  { to: "/shop", label: "Shop" }
];

const privateLinks = [
  { to: "/", label: "Home" },
  { to: "/shop", label: "Shop" },
  { to: "/cart", label: "Cart" },
  { to: "/profile", label: "Profile" }
];

export default function Navbar() {
  const { isAuthenticated, logout } = useAuth();
  const { totalItems } = useCart();
  const navigate = useNavigate();

  async function handleLogout() {
    await logout();
    navigate("/auth");
  }

  // Use private links when authenticated, public links when not
  const links = isAuthenticated ? privateLinks : publicLinks;

  return (
    <header className="sticky top-0 z-30 border-b border-rose-100 bg-white/90 backdrop-blur">
      <div className="mx-auto flex max-w-7xl items-center justify-between px-4 py-4 sm:px-6 lg:px-8">
        <div>
          <p className="font-display text-2xl font-bold text-aura-primary">AuraAR</p>
          <p className="text-sm text-stone-500">Virtual accessories try-on</p>
        </div>

        <nav className="flex flex-wrap items-center gap-2">
          {links.map((link) => (
            <NavLink
              key={link.to}
              to={link.to}
              className={({ isActive }) =>
                [
                  "relative rounded-full px-4 py-2 text-sm font-medium transition",
                  isActive
                    ? "bg-aura-primary text-white"
                    : "text-stone-600 hover:bg-rose-50 hover:text-aura-primary"
                ].join(" ")
              }
            >
              {link.label}
              {link.to === "/cart" && totalItems > 0 && (
                <span className="absolute -top-1 -right-1 flex h-5 w-5 items-center justify-center rounded-full bg-aura-accent text-xs font-bold text-white">
                  {totalItems}
                </span>
              )}
            </NavLink>
          ))}

          {isAuthenticated ? (
            <button
              type="button"
              onClick={handleLogout}
              className="rounded-full bg-aura-accent px-4 py-2 text-sm font-medium text-white transition hover:opacity-95"
            >
              Logout
            </button>
          ) : (
            <NavLink
              to="/auth"
              className={({ isActive }) =>
                [
                  "rounded-full px-4 py-2 text-sm font-medium transition",
                  isActive
                    ? "bg-aura-accent text-white"
                    : "bg-aura-secondary/20 text-aura-primary hover:bg-aura-secondary/35"
                ].join(" ")
              }
            >
              Login / Sign Up
            </NavLink>
          )}
        </nav>
      </div>
    </header>
  );
}